def check_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    numerator = (x + 1)**y
    denominator = x**z + 1

    # Since x, y, z are positive integers, both numerator and denominator are positive integers.
    # The fraction is positive, so we only need to check if it's an integer.
    if denominator == 0:
        return False # Should not happen for x >= 1

    return numerator % denominator == 0

good_triples = []
print("--- Good Triples found (1 <= x, y, z <= 10) ---")

for x in range(1, 11):
    for y in range(1, 11):
        for z in range(1, 11):
            if check_good_triple(x, y, z):
                good_triples.append((x, y, z))
                print(f"({x}, {y}, {z})")

print("\n--- Summary ---")
print(f"Total good triples found: {len(good_triples)}")

# Basic pattern analysis
print("\n--- Analysis ---")
x_counts = {}
y_counts = {}
z_counts = {}

for x, y, z in good_triples:
    x_counts[x] = x_counts.get(x, 0) + 1
    y_counts[y] = y_counts.get(y, 0) + 1
    z_counts[z] = z_counts.get(z, 0) + 1

print(f"Count of occurrences for each x: {x_counts}")
print(f"Count of occurrences for each y: {y_counts}")
print(f"Count of occurrences for each z: {z_counts}")
